import {products,glossary,dataPolicy,newest} from './data.js';
import {buildChecklist} from './rules.js';
import {dieArt,vendorColor} from './art.js';
import {initGlobalFX,observe,splitText,rail,expander,shader} from './fx.js';
const $=(q,root=document)=>root.querySelector(q),$$=(q,root=document)=>[...root.querySelectorAll(q)];
const esc=s=>String(s??'Not available').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const get=id=>products.find(p=>p.id===id);let cleanup=[],routeToken=0,compare={gpu:[],cpu:[]};
const month=r=>r.length>4?new Date(r+'-01T00:00:00').toLocaleDateString('en-GB',{month:'short',year:'numeric'}):r;
const badge=p=>p.release>='2026'?'<span class="badge hot">New in 2026</span>':newest(p)?'<span class="badge">Current gen</span>':'<span class="badge dim">Previous gen</span>';
try{const saved=JSON.parse(localStorage.getItem('atlas-compare')||'{}');for(const t of ['gpu','cpu'])compare[t]=[...new Set((saved[t]||[]).filter(id=>get(id)?.type===t))].slice(0,3)}catch{}
function save(){try{localStorage.setItem('atlas-compare',JSON.stringify(compare))}catch{}const c=$('#count'),n=compare.cpu.length+compare.gpu.length;if(c.textContent!=String(n)){c.textContent=n;c.classList.remove('bump');void c.offsetWidth;c.classList.add('bump')}}
function notify(text){$('#notice').textContent=text;$('#notice').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#notice').classList.remove('show'),3500)}
const icon=type=>type==='gpu'?`<svg viewBox="0 0 200 100" aria-hidden="true"><path d="M12 15h172v69H12zM5 8v82M24 85v8h52v-8" fill="none" stroke="currentColor" stroke-width="3"/><circle cx="60" cy="50" r="27" fill="none" stroke="currentColor" stroke-width="3"/><circle cx="139" cy="50" r="27" fill="none" stroke="currentColor" stroke-width="3"/>${[60,139].map(x=>Array.from({length:8},(_,i)=>`<path d="M${x} 50q5-24 22-13q-11 0-14 16Z" fill="currentColor" transform="rotate(${i*45} ${x} 50)"/>`).join('')).join('')}</svg>`:`<svg viewBox="0 0 200 100" aria-hidden="true"><rect x="62" y="12" width="76" height="76" fill="none" stroke="currentColor" stroke-width="3"/><rect x="76" y="26" width="48" height="48" fill="currentColor"/>${Array.from({length:8},(_,i)=>`<path d="M${68+i*9} 4v8m0 76v8M54 ${19+i*9}h8m76 0h8" stroke="currentColor" stroke-width="3"/>`).join('')}</svg>`;
function addButton(p){const on=compare[p.type].includes(p.id);return `<button class="compare-add" data-add="${p.id}" aria-pressed="${on}" aria-label="${on?'Remove':'Compare'} ${esc(p.name)}">${on?'Selected ✓':'+ Compare'}</button>`}
const statA=p=>p.type==='gpu'?[p.memory,'GB '+p.memoryType]:[p.cores,'cores · '+p.threads+' threads'];
function card(p,i=0){const [n,l]=statA(p);return `<article class="product" data-tilt style="--vc:${vendorColor[p.vendor]};--i:${i}"><div class="identity"><span class="vendor"><i></i>${esc(p.vendor)}</span>${badge(p)}</div><a class="product-art" href="#/product/${p.id}" tabindex="-1" aria-hidden="true">${dieArt(p)}</a><p class="gen">${esc(p.generation)} · ${month(p.release)}</p><h2><a href="#/product/${p.id}">${esc(p.name)}</a></h2><div class="stats"><span><strong>${n}</strong>${esc(l)}</span><span><strong>${p.power} W</strong>${esc(p.powerLabel)}</span></div><p>${p.type==='gpu'?esc(p.features.slice(2).join(' · ')):esc(p.socket)+' · '+esc(p.memoryType)}</p><div class="product-actions"><a href="#/product/${p.id}">View dossier ↗</a>${addButton(p)}</div></article>`}
function tabs(type,dest='compare'){return `<div class="tabs" aria-label="Hardware category"><a class="${type==='gpu'?'active':''}" href="#/${dest}${dest==='compare'?'?type=gpu':''}">${dest==='compare'?'Graphics cards':'GPU explorer'}</a><a class="${type==='cpu'?'active':''}" href="#/${dest==='compare'?'compare?type=cpu':'cpu'}">Processors</a></div>`}
function benchmarks(type){return `<div class="block" data-reveal><h2>Performance evidence</h2><label>Workload <select id="workload">${(type==='cpu'?['Gaming','Single-thread','Multi-thread','Application rendering']:['Rasterized gaming','Ray-traced gaming','Video editing','GPU rendering']).map(x=>`<option>${x}</option>`).join('')}</select></label><p id="benchmark-message" class="muted" style="margin-top:20px">Verified ${type==='cpu'?'gaming':'rasterized gaming'} measurements are not available in this release. Specifications are not performance scores.</p><a class="textlink" href="#/sources">How we handle benchmark data ↗</a></div>`}

const lineupIds=['ryzen-7-9850x3d','core-ultra-7-270k-plus','rtx-5090','rx-9070-xt','core-ultra-5-250k-plus','rtx-5080','ryzen-9-9950x3d','rtx-5070-ti','rx-9060-xt','core-ultra-9-285k','arc-b580','rtx-5070'];
function lineupCard(p,i){const [n,l]=statA(p);return `<a class="lineup-card" data-tilt href="#/product/${p.id}" style="--vc:${vendorColor[p.vendor]}"><span class="lineup-index">${String(i+1).padStart(2,'0')}</span><div class="lineup-top"><span class="vendor"><i></i>${esc(p.vendor)}</span>${badge(p)}</div>${dieArt(p)}<div><p class="gen">${esc(p.generation)} · ${month(p.release)}</p><h3>${esc(p.name)}</h3><div class="lineup-stats"><span><strong>${n}</strong>${esc(l)}</span><span><strong>${p.power}<small>W</small></strong>${esc(p.powerLabel)}</span></div></div></a>`}
function bars(list,key,unit,title,note){const max=Math.max(...list.map(p=>p[key]));return `<figure class="bars" aria-labelledby="bt-${key}"><figcaption id="bt-${key}"><strong>${title}</strong><span>${note}</span></figcaption><ol>${list.map((p,i)=>`<li style="--w:${(p[key]/max*100).toFixed(1)}%;--i:${i}"><a href="#/product/${p.id}"><span class="bar-name">${esc(p.name.replace(/ \d+ GB$/,''))}<small>${esc(p.vendor)}</small></span><span class="bar-track"><span class="bar-fill"></span><span class="bar-tip" role="tooltip">${esc(p.name)}: ${p[key]} ${unit}</span></span><span class="bar-val">${p[key]} ${unit}</span></a></li>`).join('')}</ol></figure>`}
function home(){
 const fresh=products.filter(newest),gpus=fresh.filter(p=>p.type==='gpu'),cpus=fresh.filter(p=>p.type==='cpu'),lineup=lineupIds.map(get);
 const ticker=fresh.map(p=>`<span style="--vc:${vendorColor[p.vendor]}"><i></i>${esc(p.name)}</span>`).join('');
 return `<section class="hero"><canvas class="hero-bg" id="hero-bg" aria-hidden="true"></canvas><div class="hero-copy"><p class="eyebrow intro-in"><span class="pulse"></span>Snapshot 30 Oct 2026 · RTX 50 · RX 9000 · Ryzen 9000 · Core Ultra</p><h1 data-split>Find your next<br>powerhouse.</h1><p class="lede intro-in">The current desktop silicon, in one living atlas. Compare sourced specifications, see what changed in 2026, and plan what your next build needs.</p><div class="actions intro-in"><a class="button magnetic" href="#/gpu">Explore the lineup <span>↗</span></a><a class="button ghost magnetic" href="#/compare">Compare parts</a></div></div><div class="media" id="hero-scene">${icon('gpu')}</div><dl class="hero-stats intro-in"><div><dt>Parts in the atlas</dt><dd data-count="${products.length}">${products.length}</dd></div><div><dt>Top VRAM · RTX 5090</dt><dd><span data-count="32">32</span><small>GB</small></dd></div><div><dt>Most cores · Ryzen 9</dt><dd data-count="16">16</dd></div><div><dt>Newest · Mar 2026</dt><dd>270K<small>Plus</small></dd></div></dl></section>
 <div class="marquee" aria-label="Current-generation parts in the atlas"><div class="marquee-track">${ticker}${ticker}</div></div>
 <section class="video-reveal" data-expander><div class="video-frame"><video muted loop playsinline preload="metadata" poster="media/die-flythrough.jpg" aria-label="Animated flythrough across a procedurally generated chip floorplan with light pulses travelling along signal traces"><source src="media/die-flythrough.mp4" type="video/mp4"></video><div class="video-overlay"><p class="eyebrow">Inside the die</p><h2 data-reveal>Billions of switches.<br>One floorplan.</h2><p data-reveal>Every GPU and CPU here is a city of compute tiles, cache arrays and signal highways. The atlas draws each one from its real core and memory layout.</p></div></div><small class="caption">Original procedurally rendered sequence · An illustration, not a photograph of a real die</small></section>
 <section class="rail" data-rail><div class="rail-sticky"><div class="rail-head"><div><p class="eyebrow">Current generation · ${fresh.length} parts</p><h2>The 2026 lineup.</h2></div><p>No new desktop GPU generation shipped in 2026, but the CPU side moved: the Ryzen 7 9850X3D in January, then Intel’s Core Ultra 200S Plus in March. Drag through the flagships ⟶</p><span class="rail-meter"><i></i></span></div><div class="rail-track">${lineup.map(lineupCard).join('')}<a class="lineup-card more" href="#/gpu"><span>See all ${fresh.length} current parts</span><b>↗</b></a></div></div></section>
 <section class="film-section" data-scroll-scene><div class="film"><div class="film-visual" id="film-scene">${icon('gpu')}</div><div class="film-copy"><p class="eyebrow">Teardown · scroll to explode</p><h2>Power. In perspective.</h2><p>A graphics card is a system of parts. Keep scrolling to orbit the assembly and see what sits beneath the shroud.</p></div><small>Interactive 3D study · Conceptual assembly, not a retail model</small><div class="progress"></div></div></section>
 <section class="specscape"><div class="section-head"><h2 data-reveal>The numbers,<br>side by side.</h2><p data-reveal>Capacity and core counts from manufacturer specifications. Bigger is not automatically faster — these bars describe resources, not performance.</p></div><div class="bars-grid">${bars([...gpus].sort((a,b)=>b.memory-a.memory||b.units-a.units),'memory','GB','VRAM · current-gen graphics cards','Manufacturer specification, GB')}${bars([...cpus].sort((a,b)=>b.cores-a.cores||b.threads-a.threads),'cores','cores','Cores · current-gen processors','Physical cores, P + E combined for Intel')}</div></section>
 <section class="wafer"><video class="wafer-video" muted loop playsinline preload="metadata" poster="media/wafer.jpg" aria-hidden="true"><source src="media/wafer.mp4" type="video/mp4"></video><div class="wafer-copy"><div class="section-head"><h2 data-reveal>Meet your<br>next part.</h2><p data-reveal>Explore the specifications that matter, then put two or three parts side by side.</p></div><div class="explore-paths"><a class="path" data-tilt data-reveal href="#/gpu"><div class="path-art">${icon('gpu')}<span class="arrow">↗</span></div><div><h3>Graphics cards</h3><p>GeForce RTX 50, Radeon RX 9000 and Arc B580 — plus the previous generation. Memory, features, power and the space your card needs.</p></div><span>${products.filter(p=>p.type==='gpu').length} graphics cards · ${gpus.length} current gen</span></a><a class="path" data-tilt data-reveal href="#/cpu"><div class="path-art">${icon('cpu')}<span class="arrow">↗</span></div><div><h3>Processors</h3><p>Ryzen 9000 and Core Ultra 200S, including the 2026 9850X3D and 200S Plus. Cores, platforms, memory and the foundation of your build.</p></div><span>${products.filter(p=>p.type==='cpu').length} processors · ${cpus.length} current gen</span></a></div></div><small class="caption">Rendered wafer loop · Original illustration</small></section>
 <section class="feature-strip"><div data-reveal><span class="num">01</span><h3>Beyond the bigger number.</h3><p>More cores or memory does not automatically mean faster. Understand the specification before choosing the part.</p><a class="textlink" href="#/sources">Learn the language ↗</a></div><div data-reveal><span class="num">02</span><h3>Compare like with like.</h3><p>Keep CPUs and GPUs in separate comparisons. Missing performance evidence stays missing, rather than becoming a guess.</p><a class="textlink" href="#/compare">Open comparison ↗</a></div><div data-reveal><span class="num">03</span><h3>The whole build matters.</h3><p>A socket is only the beginning. AM5, LGA1851 and LGA1700 each bring their own BIOS, memory and cooler questions.</p><a class="textlink" href="#/build">Plan your upgrade ↗</a></div></section>
 <section class="closing"><h2 data-reveal>Find the right<br>combination.</h2><div data-reveal><p>One part is a possibility.<br>A considered build brings it together.</p><a class="button magnetic" href="#/build">Build around your choice ↗</a></div></section>`}
let filterState={};
function explorer(type){const list=products.filter(p=>p.type===type),sel=(name,label,values)=>`<label>${label}<select name="${name}"><option value="">All ${label.toLowerCase()}</option>${values.map(v=>`<option>${esc(v)}</option>`).join('')}</select></label>`;return `<div class="page" data-ui><div class="page-title"><div><p class="eyebrow">${list.filter(newest).length} current gen · ${list.length} total</p><h1 data-split>${type==='gpu'?'Graphics cards':'Processors'}</h1><p class="muted">${type==='gpu'?'GeForce RTX 50, Radeon RX 9000, Arc B-Series — and the generation before.':'Ryzen 9000 and Core Ultra 200S, with 2026’s newest — and the generation before.'}</p></div><a class="textlink" href="#/compare?type=${type}">Open ${type.toUpperCase()} comparison ↗</a></div><form class="filters" id="filters"><label>Search hardware<input name="search" type="search" placeholder="${type==='gpu'?'Try RTX 5070 or Radeon':'Try 9850X3D or Core Ultra'}" autocomplete="off"></label>${sel('vendor','Manufacturers',[...new Set(list.map(p=>p.vendor))])}<button type="button" class="filter-toggle" aria-expanded="false">More filters</button><div class="filter-extra">${sel('generation','Generations',[...new Set(list.map(p=>p.generation))])}${type==='gpu'?sel('memory','Minimum VRAM',['8','12','16','20','24','32'])+sel('power','Maximum power',['150','250','350','450','600'])+sel('feature','Features',['Ray tracing','AV1 encode','DLSS','DLSS 4','Multi Frame Generation','FSR','FSR 4','XeSS 2']):sel('socket','Sockets',['AM5','LGA1851','LGA1700'])+sel('cores','Minimum cores',['4','6','8','12','16','20','24'])+sel('igpu','Integrated graphics',['Yes','No'])+sel('memoryType','Memory types',['DDR4','DDR5'])}</div><button type="reset">Reset</button></form><div class="results-bar"><span id="result-count" role="status"></span><label>Sort <select id="sort"><option value="newest">Newest first</option><option value="name">Name</option><option value="power">Power: low to high</option><option value="capacity">${type==='gpu'?'VRAM':'Cores'}: high to low</option></select></label></div><div id="results" class="product-list"></div><p class="source-note" style="margin-top:25px">Floorplan drawings are schematic illustrations generated from each part’s specifications — not die photos or product photographs. Live prices and comparable performance datasets are not included.</p></div>`}
function updateResults(type){const f=Object.fromEntries(new FormData($('#filters')));filterState[type]={...f,sort:$('#sort').value};let list=products.filter(p=>p.type===type&&(!f.search||`${p.name} ${p.vendor} ${p.generation}`.toLowerCase().includes(f.search.toLowerCase()))&&(!f.vendor||p.vendor===f.vendor)&&(!f.generation||p.generation===f.generation)&&(!f.memory||p.memory>=Number(f.memory))&&(!f.power||p.power<=Number(f.power))&&(!f.feature||p.features.includes(f.feature))&&(!f.socket||p.socket===f.socket)&&(!f.cores||p.cores>=Number(f.cores))&&(!f.igpu||p.igpu===(f.igpu==='Yes'))&&(!f.memoryType||p.memoryType.includes(f.memoryType)));const sort=$('#sort').value;list.sort((a,b)=>sort==='newest'?b.release.localeCompare(a.release)||(b.units||0)-(a.units||0):sort==='power'?a.power-b.power:sort==='capacity'?(b.memory||b.cores)-(a.memory||a.cores):a.name.localeCompare(b.name));$('#result-count').textContent=`${list.length} ${type==='gpu'?'graphics cards':'processors'}${Object.values(f).some(Boolean)?' · Filters applied':''}`;$('#results').innerHTML=list.length?list.map(card).join(''):'<div class="empty"><h2>No matching hardware.</h2><p>Try a broader search or reset your filters.</p><button id="clear-empty">Reset filters</button></div>';$('#clear-empty')?.addEventListener('click',()=>{$('#filters').reset();setTimeout(()=>updateResults(type),0)})}
const num=v=>{const m=String(v).match(/[\d.]+/);return m?parseFloat(m[0]):null};
function meters(selected,type){const rows=(type==='gpu'?[['VRAM',p=>p.memory,'GB'],['Power specification',p=>p.power,'W'],['Memory bus',p=>num(p.specs['Memory interface']),'-bit']]:[['Cores',p=>p.cores,''],['Threads',p=>p.threads,''],['Power specification',p=>p.power,'W']]);return `<div class="meters" data-reveal>${rows.map(([label,val,unit])=>{const max=Math.max(...selected.map(p=>val(p)||0))||1;return `<div class="meter"><h3>${label}</h3>${selected.map((p,i)=>`<div class="meter-row" style="--w:${((val(p)||0)/max*100).toFixed(1)}%;--i:${i}"><span>${esc(p.name)}</span><span class="bar-track"><span class="bar-fill"></span></span><b>${val(p)??'—'}${unit==='-bit'?'':' '}${unit}</b></div>`).join('')}</div>`}).join('')}<p class="source-note">${type==='gpu'?'Capacity and bus width are resources, not speed rankings.':'Intel P- and E-cores are counted together; they are not identical cores.'} Power definitions differ by vendor.</p></div>`}
function comparison(type,params){if(params.has('ids')){compare[type]=[...new Set(params.get('ids').split(',').filter(id=>get(id)?.type===type))].slice(0,3);save()}const selected=compare[type].map(get);const rows=[...new Set(selected.flatMap(p=>Object.keys(p.specs)))];return `<div class="page" data-ui><div class="page-title"><div><h1 data-split>Compare your options.</h1><p class="muted">The details side by side. The tradeoffs in plain language.</p></div><button id="share" class="magnetic">Copy comparison link ↗</button></div>${tabs(type)}<div class="selectors">${[0,1,2].map((i)=>{const p=selected[i];return `<div class="selector ${p?'filled':''}" style="${p?`--vc:${vendorColor[p.vendor]}`:''}">${p?`<div class="selector-art">${dieArt(p,{label:false})}</div>`:''}<label for="find-${i}">${i===2?'Optional third part':'Choose '+(i===0?'first':'second')+' part'}</label><input id="find-${i}" type="search" placeholder="Search ${type==='gpu'?'graphics cards':'processors'}" data-find="${i}" aria-label="Search slot ${i+1}"><select data-select="${i}" aria-label="Product in slot ${i+1}"><option value="">Select a part</option>${products.filter(p=>p.type===type).map(p2=>`<option value="${p2.id}" ${p?.id===p2.id?'selected':''} ${selected.some((s,j)=>s.id===p2.id&&j!==i)?'disabled':''}>${esc(p2.name)}</option>`).join('')}</select>${p?`<a href="#/product/${p.id}" class="textlink">Product dossier ↗</a><button data-remove="${p.id}" style="float:right" aria-label="Remove ${esc(p.name)}">Remove</button>`:'<p class="muted">Compare specifications within the same hardware category.</p>'}</div>`}).join('')}</div>${selected.length?`${selected.length>1?meters(selected,type):''}<div class="toolbar"><label><input type="checkbox" id="differences"> Show differences only</label><span class="muted">${selected.length}/3 parts selected · ${selected.length<2?'Add another part to compare.':'Different does not automatically mean better.'}</span></div><div class="table-wrap"><table><caption class="muted" style="text-align:left;padding:15px">Manufacturer specifications · scroll horizontally on small screens</caption><thead><tr><th scope="col">Specification</th>${selected.map(p=>`<th scope="col">${esc(p.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(k=>{const values=selected.map(p=>p.specs[k]||'Not available'),diff=new Set(values).size>1;return `<tr data-different="${diff}"><th scope="row">${esc(k)}</th>${values.map(v=>`<td class="${diff?'different':''}">${esc(v)}</td>`).join('')}</tr>`}).join('')}</tbody></table></div><div class="block" data-reveal><h2>What actually changes?</h2>${selected.length>1?`<p>${type==='gpu'?`These cards offer ${[...new Set(selected.map(p=>p.memory))].sort((a,b)=>a-b).join(', ')} GB of VRAM. Capacity matters when your workload needs it; it is not a speed ranking.`:`These processors use ${[...new Set(selected.map(p=>p.socket))].join(' and ')}. A platform change can require a new motherboard and memory.`}</p><p>Power ratings range from ${Math.min(...selected.map(p=>p.power))} to ${Math.max(...selected.map(p=>p.power))} W. Manufacturer definitions can differ. Check cooling, connectors and your whole system; do not interpret watts as performance.</p>`:'<p>Select another product to see the meaningful differences.</p>'}<a class="textlink" href="#/build?${type}=${selected[0].id}">Check supporting components ↗</a></div>`:'<div class="empty" style="margin-top:24px"><h2>Two parts. A clearer decision.</h2><p>Select your first two CPUs or GPUs above. Your comparison can be shared with its own link.</p></div>'}${benchmarks(type)}</div>`}
function detail(id){const p=get(id);if(!p)return '<div class="page"><h1>Part not found.</h1><a class="button" href="#/gpu">Explore the catalogue</a></div>';const [n,l]=statA(p),clock=num(p.specs['Boost clock']||p.specs['Maximum boost']||p.specs['Maximum turbo']||p.specs['Graphics clock']);return `<div class="page detail" data-ui style="--vc:${vendorColor[p.vendor]}"><a class="crumb" href="#/${p.type}">← ${p.type==='gpu'?'Graphics cards':'Processors'}</a><div class="detail-hero"><div class="detail-art" data-tilt>${dieArt(p)}<small>Schematic floorplan generated from this part’s specifications · Not a die photo</small></div><div><p class="eyebrow"><span class="vendor"><i></i>${esc(p.vendor)}</span> · ${esc(p.generation)} · ${month(p.release)} ${badge(p)}</p><h1 data-split>${esc(p.name)}</h1><dl class="detail-stats"><div><dt>${esc(l)}</dt><dd data-count="${n}">${n}</dd></div><div><dt>${esc(p.powerLabel)}</dt><dd><span data-count="${p.power}">${p.power}</span><small>W</small></dd></div>${clock?`<div><dt>Max clock</dt><dd><span data-count="${clock}">${clock}</span><small>GHz</small></dd></div>`:''}</dl><p>${esc(p.notes)}</p><div class="actions">${addButton(p)}<a class="button magnetic" href="#/build?${p.type}=${p.id}">Build around this part ↗</a></div><p class="source-note" style="margin-top:25px">Snapshot ${p.verified} · <a href="${esc(p.source)}" target="_blank" rel="noopener">Manufacturer source ↗</a></p></div></div><div class="two-col"><div class="block" data-reveal><h2>Specification dossier</h2><div class="table-wrap"><table style="min-width:0"><tbody>${Object.entries(p.specs).map(([k,v],i)=>`<tr style="--i:${i}"><th scope="row">${esc(k)}</th><td>${esc(v)}</td></tr>`).join('')}</tbody></table></div></div><div><div class="block" data-reveal><h2>Build around this part</h2><ul class="requirements">${p.requirements.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><a class="textlink" href="#/build?${p.type}=${p.id}">Personalize your checklist ↗</a></div>${benchmarks(p.type)}</div></div><div class="block" data-reveal><h2>Explore alternatives</h2><div class="alt-grid">${products.filter(x=>x.type===p.type&&x.id!==p.id).sort((a,b)=>Math.abs(a.power-p.power)-Math.abs(b.power-p.power)).slice(0,3).map(x=>`<a class="alt" data-tilt style="--vc:${vendorColor[x.vendor]}" href="#/compare?type=${p.type}&ids=${p.id},${x.id}">${dieArt(x,{label:false})}<span>Compare with<br><b>${esc(x.name)}</b> ↗</span></a>`).join('')}</div></div></div>`}
function build(params){const options=t=>`<option value="">Not selected</option>${products.filter(p=>p.type===t).map(p=>`<option value="${p.id}" ${params.get(t)===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}`;return `<div class="page" data-ui><div class="page-title"><div><h1 data-split>Build with the whole picture.</h1><p class="muted">Turn your parts into a practical checklist. No invented compatibility scores.</p></div></div><div class="two-col"><form id="build-form" class="block" style="margin-top:0"><h2>Your upgrade</h2><div class="build-form"><label>Target processor<select name="targetCpu">${options('cpu')}</select></label><label>Target graphics card<select name="targetGpu">${options('gpu')}</select></label><label>Existing CPU<input name="existingCpu" placeholder="e.g. Ryzen 5 3600"></label><label>Existing GPU<input name="existingGpu" placeholder="e.g. GeForce GTX 1660"></label><label>Motherboard model<input name="motherboard" placeholder="Exact model, if known"></label><label>Existing socket<select name="socket"><option value="">Unknown</option><option>AM4</option><option>AM5</option><option>LGA1700</option><option>LGA1200</option><option>LGA1851</option></select></label><label>RAM type<select name="ramType"><option value="">Unknown</option><option>DDR4</option><option>DDR5</option><option>DDR3</option></select></label><label>RAM capacity (GB)<input name="ramCapacity" type="number" min="1" max="2048" placeholder="32"></label><label>PSU model / wattage<input name="psu" placeholder="e.g. exact model, 750 W"></label><label>GPU length clearance (mm)<input type="number" name="clearance" min="1" max="1000" placeholder="340"></label><label>Monitor resolution / refresh<input name="monitor" placeholder="2560 × 1440, 165 Hz"></label><label>Main workload<select name="use"><option>Gaming</option><option>Video editing</option><option>3D rendering</option><option>Software development</option><option>General use</option></select></label><label class="full">Approximate budget (include currency)<input name="budget" placeholder="Optional — pricing is not integrated"></label><button class="button full" type="submit">Create my checklist ↗</button></div><p class="source-note" style="margin-top:20px">Saved in this browser only. Nothing is sent to a server.</p></form><div><div class="block" style="margin-top:0"><h2>Your build checklist</h2><div id="checklist" aria-live="polite"><p>Choose your target parts and enter what you know. Unknown details will remain verification tasks.</p><p class="muted">A matching CPU socket does not confirm motherboard support. PSU wattage does not confirm cable compatibility.</p></div></div><div class="block" data-reveal><h2>What this can establish</h2><p>Socket and memory-generation mismatches. Part-specific checks for BIOS, cooling, case clearance and power connections.</p><p class="muted">Exact motherboard support, PSU quality and application performance require model-specific documentation or measurements.</p></div></div></div></div>`}
function sources(){return `<div class="page" data-ui><div class="page-title"><div><h1 data-split>Evidence before advice.</h1><p class="muted">What the atlas knows, where it comes from, and what remains unknown.</p></div></div><div class="two-col"><div class="block" data-reveal><h2>Scope & verification</h2><p>${esc(dataPolicy.scope)}</p><p>Specifications are a snapshot taken 30 October 2026 against manufacturer pages, not a live feed. Each product dossier links to its source. Intel’s Core Ultra 200S Plus values were cross-checked against launch spec tables; recheck Intel’s product page before purchase.</p><p>Board-partner GPU coolers, dimensions, connectors and power limits may differ. Always verify the exact retail model.</p></div><div class="block" data-reveal><h2>Performance, honestly</h2><p>${esc(dataPolicy.benchmarkStatus)}</p><p>Future results must include application, test date, platform and software versions. Gaming records also need resolution, quality, ray tracing, upscaling and frame-generation state. Average FPS and percentile lows remain distinct.</p><p>Only matched test conditions may be compared. A derived change would use (new measurement − baseline) ÷ baseline × 100. Lower is better for elapsed time; higher is better for throughput.</p></div><div class="block" data-reveal><h2>Images, video & pricing</h2><p>${esc(dataPolicy.imageStatus)}</p><p>Every visual is original. Product floorplans are schematic SVGs generated from each record’s execution units, memory bus and core layout. The die flythrough and wafer loops are procedurally rendered videos. The 3D card is a conceptual model, not a retail product or an accurate teardown.</p><p>${esc(dataPolicy.priceStatus)}</p><p>3D rendering uses Three.js, MIT licensed. <a class="textlink" href="vendor/THREE-LICENSE.txt">Read the license</a></p></div><div class="block" data-reveal><h2>Manufacturer references</h2><ul class="source-list">${[...new Map(products.map(p=>[p.source,p])).values()].map(p=>`<li><a href="${esc(p.source)}" target="_blank" rel="noopener">${esc(p.vendor==='NVIDIA'?'NVIDIA GeForce specification comparison':p.source.includes('core-ultra.html')?'Intel Core Ultra processors':p.name)} ↗</a></li>`).join('')}</ul></div></div><section style="padding:60px 0 0"><h2>The hardware glossary</h2><div class="glossary">${glossary.map(g=>`<details data-reveal><summary>${esc(g.term)}</summary><p>${esc(g.definition)}</p></details>`).join('')}</div></section></div>`}
async function render(){const token=++routeToken;cleanup.forEach(f=>f());cleanup=[];const [path,query='']=(location.hash.slice(1)||'/').split('?'),params=new URLSearchParams(query),type=params.get('type')==='cpu'?'cpu':'gpu';$('#navigation').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');$$('nav a').forEach(a=>{if(a.hash.split('?')[0]==='#'+path)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const main=$('#main');main.innerHTML=path==='/'?home():path==='/gpu'||path==='/cpu'?explorer(path.slice(1)):path==='/compare'?comparison(type,params):path.startsWith('/product/')?detail(path.split('/')[2]):path==='/build'?build(params):path==='/sources'?sources():'<div class="page"><h1>Page not found.</h1><a href="#/">Return to the atlas</a></div>';document.title=`${$('h1')?.innerText.replace(/\s+/g,' ')||'Hardware guide'} — SILICON ATLAS`;main.classList.remove('enter');void main.offsetWidth;main.classList.add('enter');scrollTo(0,0);main.focus({preventScroll:true});save();splitText(main);
 if(path==='/'){$$('[data-rail]').forEach(s=>cleanup.push(rail(s)));$$('[data-expander],.wafer').forEach(s=>cleanup.push(expander(s)));cleanup.push(shader($('#hero-bg')));try{const {mountHardware}=await import('./scene.js');if(token===routeToken){cleanup.push(mountHardware($('#hero-scene')));cleanup.push(mountHardware($('#film-scene'),{scrollSection:$('.film-section')}))}}catch{if(token===routeToken){$('#hero-scene').innerHTML=icon('gpu');$('#film-scene').innerHTML=icon('gpu')}}}
 if(path==='/gpu'||path==='/cpu'){const t=path.slice(1);for(const [key,value]of Object.entries(filterState[t]||{}))if($('#filters').elements[key])$('#filters').elements[key].value=value;if(filterState[t]?.sort)$('#sort').value=filterState[t].sort;updateResults(t);$('#filters').addEventListener('submit',e=>e.preventDefault());$('#filters').addEventListener('input',()=>updateResults(t));$('#filters').addEventListener('reset',()=>setTimeout(()=>updateResults(t),0));$('#sort').onchange=()=>updateResults(t);$('.filter-toggle').onclick=e=>{const open=$('#filters').classList.toggle('expanded');e.target.setAttribute('aria-expanded',open);e.target.textContent=open?'Fewer filters':'More filters'}}
 if(path==='/compare'){$$('[data-select]').forEach(el=>el.onchange=()=>{let ids=[...compare[type]];ids[Number(el.dataset.select)]=el.value;compare[type]=ids.filter(Boolean);save();location.hash=`/compare?type=${type}&ids=${compare[type].join(',')}`});$$('[data-find]').forEach(el=>el.oninput=()=>{const s=$(`[data-select="${el.dataset.find}"]`);[...s.options].forEach(o=>{o.hidden=!!o.value&&!o.text.toLowerCase().includes(el.value.toLowerCase())})});$('#differences')?.addEventListener('change',e=>$$('tr[data-different=false]').forEach(r=>r.hidden=e.target.checked));$('#share').onclick=async()=>{const url=new URL(location.href);url.hash=`/compare?type=${type}&ids=${compare[type].join(',')}`;try{await navigator.clipboard.writeText(url.href);notify('Comparison link copied.')}catch{prompt('Copy this comparison link',url.href)}}}
 if(path==='/build'){const form=$('#build-form');try{const saved=JSON.parse(localStorage.getItem('atlas-build')||'{}');for(const [key,value]of Object.entries(saved))if(form.elements[key]&&!((key==='targetCpu'&&params.has('cpu'))||(key==='targetGpu'&&params.has('gpu'))))form.elements[key].value=value}catch{}form.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));try{localStorage.setItem('atlas-build',JSON.stringify(data))}catch{}const list=buildChecklist(data,products);$('#checklist').innerHTML=`<p>${esc(data.motherboard?'Motherboard: '+data.motherboard:'Exact motherboard not specified')}${data.ramCapacity?' · '+esc(data.ramCapacity)+' GB RAM':''}</p><ul class="checklist">${list.map((i,n)=>`<li data-status="${esc(i.status)}" style="--i:${n}"><strong>${esc(i.status)} · ${esc(i.title)}</strong>${esc(i.text)}</li>`).join('')}</ul><p class="source-note">This checklist flags known mismatches and open questions. It is not a guarantee that the complete PC will work.</p>`;$('#checklist').scrollIntoView({behavior:'smooth',block:'start'})}}
 $('#workload')?.addEventListener('change',e=>{$('#benchmark-message').textContent=`Verified ${e.target.value.toLowerCase()} measurements are not available in this release. No ranking or performance percentage can be established from specifications alone.`});
 cleanup.push(observe(main));
}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-add],[data-remove]');if(!btn)return;const p=get(btn.dataset.add||btn.dataset.remove);if(!p)return;const ids=compare[p.type],index=ids.indexOf(p.id);if(index>=0)ids.splice(index,1);else if(ids.length<3)ids.push(p.id);else return notify('Three parts selected. Remove one in Compare to add another.');save();if(location.hash.startsWith('#/compare')){location.hash=`/compare?type=${p.type}&ids=${ids.join(',')}`}else{$$(`[data-add="${p.id}"]`).forEach(b=>{b.setAttribute('aria-pressed',ids.includes(p.id));b.textContent=ids.includes(p.id)?'Selected ✓':'+ Compare';b.setAttribute('aria-label',`${ids.includes(p.id)?'Remove':'Compare'} ${p.name}`)});notify(`${p.name} ${ids.includes(p.id)?'added to':'removed from'} ${p.type.toUpperCase()} comparison.`)}});
$('#menu').onclick=()=>{const open=$('#navigation').classList.toggle('open');$('#menu').setAttribute('aria-expanded',open)};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#navigation').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')}});
initGlobalFX();window.addEventListener('hashchange',render);render().then(()=>setTimeout(()=>document.body.classList.add('booted'),900));
